import{_ as a,o as e,c as l,a2 as i}from"./chunks/framework.z3u3TMv0.js";const u=JSON.parse('{"title":"30 分クイックスタート","description":"ゼロから MiniTavern がローカルモデルの最初の返信を受け取るまで：Ollama または LM Studio、モデル導入、LAN 接続、約 30 分。","frontmatter":{"title":"30 分クイックスタート","description":"ゼロから MiniTavern がローカルモデルの最初の返信を受け取るまで：Ollama または LM Studio、モデル導入、LAN 接続、約 30 分。","head":[["meta",{"name":"keywords","content":"酒場,AI酒場,MiniTavern,AI相棒,AI友達,AIローカルチャット,Silly Tavern,SillyTavern,スマホでSilly Tavern,Silly Tavernスマホ版,Silly Tavern Android,Silly Tavern iOS,AIロールプレイ,キャラクターカード,AIチャット,スマホAI,オフラインAI,AIストーリー,ローカルLLM,Ollama,LM Studio,ワールドブック,正規表現,BYOK,ユーザーガイド,マニュアル"}],["meta",{"property":"og:title","content":"30 分クイックスタート · MiniTavern Docs"}],["meta",{"property":"og:description","content":"ゼロから MiniTavern がローカルモデルの最初の返信を受け取るまで：Ollama または LM Studio、モデル導入、LAN 接続、約 30 分。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ja/quickstart"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ja/quickstart"}]]},"headers":[],"relativePath":"ja/quickstart.md","filePath":"ja/quickstart.md","lastUpdated":1787224147000}'),r={name:"ja/quickstart.md"};function o(s,t,n,d,p,h){return e(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="_30-分クイックスタート" tabindex="-1">30 分クイックスタート <a class="header-anchor" href="#_30-分クイックスタート" aria-label="Permalink to &quot;30 分クイックスタート&quot;">​</a></h1><p>目標：ゼロから、MiniTavern でローカルモデルの最初の返信を受け取る。</p><table tabindex="0"><thead><tr><th>ステップ</th><th>おおよそ</th><th>内容</th></tr></thead><tbody><tr><td>1</td><td>0–5 min</td><td>ツール選択：Ollama または LM Studio</td></tr><tr><td>2</td><td>5–15 min</td><td>インストールし小モデルを取得</td></tr><tr><td>3</td><td>15–20 min</td><td>LAN／Local Server を有効化</td></tr><tr><td>4</td><td>20–25 min</td><td>PC の LAN IP を調べる</td></tr><tr><td>5</td><td>25–30 min</td><td>MiniTavern で接続を新規作成し測連</td></tr></tbody></table><hr><h2 id="step-1-ツールを選ぶ" tabindex="-1">Step 1：ツールを選ぶ <a class="header-anchor" href="#step-1-ツールを選ぶ" aria-label="Permalink to &quot;Step 1：ツールを選ぶ&quot;">​</a></h2><ul><li><strong>最速</strong>： <a href="/ultra_guides/ja/ollama/install">Ollama</a> または <a href="/ultra_guides/ja/lmstudio/install">LM Studio</a></li><li><strong>ロールプレイ向け</strong>：後で <a href="/ultra_guides/ja/koboldcpp/install">KoboldCPP</a> に替えられる</li><li><strong>すでに GGUF がある</strong>：<a href="/ultra_guides/ja/llamacpp/install">llama.cpp</a></li></ul><p>完全比較は <a href="/ultra_guides/ja/local/tools">ツール一覧</a>。以下は <strong>Ollama</strong> の通関手順；他ツールは「モデル取得／サービス開始」を対応章に差し替え、Step 5 は同じ。</p><hr><h2 id="step-2-インストールし小モデルを-pull" tabindex="-1">Step 2：インストールし小モデルを pull <a class="header-anchor" href="#step-2-インストールし小モデルを-pull" aria-label="Permalink to &quot;Step 2：インストールし小モデルを pull&quot;">​</a></h2><ol><li><a href="/ultra_guides/ja/ollama/install">Ollama インストール</a> に従う。</li><li>端末で（例、体積が相対的に小さく通路検証向き）：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> llama3.2:3b</span></span></code></pre></div><ol start="3"><li>本機で使えることを確認：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> llama3.2:3b</span></span></code></pre></div><p>対話できたら <code>/bye</code> で終了。モデル選びは <a href="/ultra_guides/ja/ollama/models">モデルの取得と選択</a>。</p><hr><h2 id="step-3-lan-アクセスを有効化" tabindex="-1">Step 3：LAN アクセスを有効化 <a class="header-anchor" href="#step-3-lan-アクセスを有効化" aria-label="Permalink to &quot;Step 3：LAN アクセスを有効化&quot;">​</a></h2><p><a href="/ultra_guides/ja/ollama/lan">LAN アクセスの有効化</a> に従い <code>OLLAMA_HOST=0.0.0.0</code> を設定し、ファイアウォールでポート <strong>11434</strong> を開放。</p><p>完了後、<strong>PC 本機</strong>ブラウザで（応答があればよく、美しいページでなくてよい）：</p><p><code>http://127.0.0.1:11434</code></p><hr><h2 id="step-4-pc-の-lan-ip-を調べる" tabindex="-1">Step 4：PC の LAN IP を調べる <a class="header-anchor" href="#step-4-pc-の-lan-ip-を調べる" aria-label="Permalink to &quot;Step 4：PC の LAN IP を調べる&quot;">​</a></h2><ul><li><strong>Windows</strong>：<code>Win + R</code> → <code>cmd</code> → <code>ipconfig</code>、「ワイヤレス LAN アダプター」下の <strong>IPv4 アドレス</strong>（形は <code>192.168.x.x</code>）。</li><li><strong>macOS</strong>：システム設定 → ネットワーク → 現在の Wi‑Fi → 詳細の IP；または端末で <code>ipconfig getifaddr en0</code>。</li></ul><p>この IP を控え、以降 <code>YOUR_PC_IP</code> とする。</p><hr><h2 id="step-5-minitavern-で設定" tabindex="-1">Step 5：MiniTavern で設定 <a class="header-anchor" href="#step-5-minitavern-で設定" aria-label="Permalink to &quot;Step 5：MiniTavern で設定&quot;">​</a></h2><ol><li>App → <strong>設定 → モデル → モデル接続 → 新規</strong>。</li><li>プラットフォームは <strong>カスタム／OpenAI 互換</strong>（App 内の実際の選択肢名準拠）。</li><li>記入：</li></ol><table tabindex="0"><thead><tr><th>フィールド</th><th>例（Ollama）</th></tr></thead><tbody><tr><td>Base URL</td><td><code>http://YOUR_PC_IP:11434/v1</code></td></tr><tr><td>API Key</td><td>空欄または任意プレースホルダ（ローカルは通常検証しない）</td></tr><tr><td>モデル名</td><td><code>llama3.2:3b</code>（<code>ollama list</code> と一致）</td></tr></tbody></table><ol start="4"><li>保存して <strong>測連</strong>；成功後デフォルトにし、キャラカードを取り込んで開聊。</li></ol><p>UI の詳細は <a href="/ultra_guides/ja/connect-app/minitavern">MiniTavern での設定</a>。</p><hr><h2 id="失敗したら" tabindex="-1">失敗したら？ <a class="header-anchor" href="#失敗したら" aria-label="Permalink to &quot;失敗したら？&quot;">​</a></h2><ul><li>測連失敗、タイムアウト、空白返信 → <a href="/ultra_guides/ja/troubleshoot">排錯対照表</a></li><li>いちばん多い誤り：<strong>Base URL を <code>localhost</code> にした</strong>、またはスマホと PC が同一 Wi‑Fi でない</li></ul>',32)])])}const g=a(r,[["render",o]]);export{u as __pageData,g as default};
